#!/usr/bin/env node
// Generates the admin's design-system files from shared/design/tokens.json and icons.json.
// Run from the repo root: `npm run tokens`. Never edit the generated files by hand.
//
// Outputs:
//   frontend/src/styles/raad-tokens.css        CSS variables, Tailwind theme, text-style utilities
//   frontend/src/components/icons/icon-paths.ts  icon name → SVG inner markup

import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..');
const tokens = JSON.parse(readFileSync(join(here, 'tokens.json'), 'utf8'));
const { icons } = JSON.parse(readFileSync(join(here, 'icons.json'), 'utf8'));

const HEADER =
  '/* GENERATED by shared/design/build-tokens.mjs from shared/design/tokens.json. Do not edit. */';

/** "navy.900" → "var(--navy-900)", "white" → "var(--white)". */
function ref(path) {
  const parts = path.split('.');
  let value = tokens.color;
  for (const p of parts) value = value?.[p];
  if (typeof value !== 'string') throw new Error(`Unknown color reference: ${path}`);
  return `var(--${parts.join('-')})`;
}

const fontStack = {
  display: 'var(--font-outfit), ui-sans-serif, system-ui, sans-serif',
  body: 'var(--font-inter), ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif',
  mono: 'var(--font-jetbrains-mono), ui-monospace, SFMono-Regular, Menlo, monospace',
};

const vars = [];
const theme = [];

// Primitive colors.
for (const [name, value] of Object.entries(tokens.color)) {
  if (typeof value === 'string') {
    vars.push(`--${name}: ${value};`);
    theme.push(`--color-${name}: var(--${name});`);
    continue;
  }
  for (const [step, hex] of Object.entries(value)) {
    vars.push(`--${name}-${step}: ${hex};`);
    theme.push(`--color-${name}-${step}: var(--${name}-${step});`);
  }
}

// Semantic colors, mapped onto Tailwind's per-property namespaces so class names match Figma:
// bg-app, bg-brand, text-muted, text-on-brand, border-strong…
for (const [name, target] of Object.entries(tokens.semantic)) {
  vars.push(`--${name}: ${ref(target)};`);
  const [kind, ...rest] = name.split('-');
  const short = rest.join('-');
  if (kind === 'bg') theme.push(`--background-color-${short}: var(--${name});`);
  else if (kind === 'text') theme.push(`--text-color-${short}: var(--${name});`);
  else if (kind === 'border') theme.push(`--border-color-${short}: var(--${name});`);
  else theme.push(`--color-${name}: var(--${name});`);
}

// Status colors: bg-status-late-bg, text-status-late-fg…
for (const [name, s] of Object.entries(tokens.status)) {
  vars.push(`--status-${name}-bg: ${ref(s.bg)};`, `--status-${name}-fg: ${ref(s.fg)};`);
  theme.push(
    `--color-status-${name}-bg: var(--status-${name}-bg);`,
    `--color-status-${name}-fg: var(--status-${name}-fg);`,
  );
}

// Fonts.
for (const [name, stack] of Object.entries(fontStack)) {
  vars.push(`--font-${name}-stack: ${stack};`);
}
theme.push(
  '--font-display: var(--font-display-stack);',
  '--font-sans: var(--font-body-stack);',
  '--font-body: var(--font-body-stack);',
  '--font-mono: var(--font-mono-stack);',
  '--font-heading: var(--font-display-stack);',
);

// Space (4-pt). Tailwind's default spacing is already 4px per step, so p-4 = 16px = --s-4.
for (const [step, px] of Object.entries(tokens.space)) vars.push(`--s-${step}: ${px}px;`);

// Radius.
for (const [name, px] of Object.entries(tokens.radius)) {
  vars.push(`--r-${name}: ${px}px;`);
  theme.push(`--radius-${name}: var(--r-${name});`);
}

// Shadows (navy-tinted elevation).
for (const [name, value] of Object.entries(tokens.shadow)) {
  vars.push(`--shadow-raad-${name}: ${value};`);
  theme.push(`--shadow-${name}: var(--shadow-raad-${name});`);
}

// Motion.
for (const [name, ms] of Object.entries(tokens.motion.duration))
  vars.push(`--dur-${name}: ${ms}ms;`);
for (const [name, curve] of Object.entries(tokens.motion.easing)) {
  vars.push(`--raad-ease-${name}: cubic-bezier(${curve.join(', ')});`);
  theme.push(`--ease-${name}: var(--raad-ease-${name});`);
}

// Text styles → `text-h1`, `text-eta`, `text-admin-h1`… (font, size, line height, weight, tracking).
const utilities = Object.entries(tokens.text).map(([name, t]) => {
  const lines = [
    `font-family: var(--font-${t.font}-stack);`,
    `font-size: ${t.size}px;`,
    `line-height: ${t.lineHeight}px;`,
    `font-weight: ${t.weight};`,
    `letter-spacing: ${t.tracking}em;`,
  ];
  if (t.uppercase) lines.push('text-transform: uppercase;');
  if (t.tabular) lines.push('font-variant-numeric: tabular-nums;');
  return `@utility text-${name} {\n  ${lines.join('\n  ')}\n}`;
});

const css = [
  HEADER,
  '',
  ':root {',
  ...vars.map((v) => `  ${v}`),
  '}',
  '',
  '@theme inline {',
  ...theme.map((t) => `  ${t}`),
  '}',
  '',
  utilities.join('\n\n'),
  '',
  '/* Always emit every text style, even when only used through a dynamic class name. */',
  `@source inline("text-{${Object.keys(tokens.text).join(',')}}");`,
  '',
  '/* Tabular figures for ETAs, times, counts and tables. */',
  '@utility tabular {\n  font-variant-numeric: tabular-nums;\n}',
  '',
].join('\n');

const cssPath = join(root, 'frontend', 'src', 'styles', 'raad-tokens.css');
mkdirSync(dirname(cssPath), { recursive: true });
writeFileSync(cssPath, css);

const names = Object.keys(icons);
const ts = [
  '// GENERATED by shared/design/build-tokens.mjs from shared/design/icons.json. Do not edit.',
  '',
  '/** SVG inner markup for each Raad icon (24×24 viewBox, stroke-based, uses currentColor). */',
  'export const iconPaths = {',
  ...names.map((n) => `  ${JSON.stringify(n)}: ${JSON.stringify(icons[n])},`),
  '} as const;',
  '',
  'export type IconName = keyof typeof iconPaths;',
  '',
].join('\n');

const iconPath = join(root, 'frontend', 'src', 'components', 'icons', 'icon-paths.ts');
mkdirSync(dirname(iconPath), { recursive: true });
writeFileSync(iconPath, ts);

const statusTs = [
  '// GENERATED by shared/design/build-tokens.mjs from shared/design/tokens.json. Do not edit.',
  '',
  "import type { IconName } from '../icons/icon-paths';",
  '',
  '/** Trip and bus statuses. Every status is shown as icon + word + colour, never colour alone. */',
  'export const statusTokens = {',
  ...Object.entries(tokens.status).map(
    ([name, s]) =>
      `  ${JSON.stringify(name)}: { icon: ${JSON.stringify(s.icon)}, en: ${JSON.stringify(s.en)}, so: ${JSON.stringify(s.so)} },`,
  ),
  '} as const satisfies Record<string, { icon: IconName; en: string; so: string }>;',
  '',
  'export type Status = keyof typeof statusTokens;',
  '',
].join('\n');

const statusPath = join(root, 'frontend', 'src', 'components', 'raad', 'status-tokens.ts');
mkdirSync(dirname(statusPath), { recursive: true });
writeFileSync(statusPath, statusTs);

// ---------------------------------------------------------------------------
// Flutter (app/raad_core/lib/theme/generated/)
// ---------------------------------------------------------------------------

const DART_HEADER =
  '// GENERATED by shared/design/build-tokens.mjs from shared/design/tokens.json. Do not edit.\n// ignore_for_file: constant_identifier_names';

/** "check-c" → "checkC", "road-edge" → "roadEdge". */
const camel = (s) => s.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
/** "#F5B400" → "Color(0xFFF5B400)". */
const dartColor = (hex) => `Color(0xFF${hex.slice(1).toUpperCase()})`;
/** "navy.900" → "navy900", "white" → "white". */
const dartRef = (path) => camel(path.replace('.', ''));
const dartString = (s) => `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

/** "0 1px 2px rgba(11,31,58,.06), 0 1px 3px rgba(…)" → BoxShadow list. */
function dartShadows(value) {
  return value.split(/,(?![^(]*\))/).map((part) => {
    const m = part
      .trim()
      .match(
        /^(-?\d+)(?:px)? (-?\d+)(?:px)? (\d+)(?:px)?(?: (-?\d+)(?:px)?)? rgba\((\d+),(\d+),(\d+),([\d.]+)\)$/,
      );
    if (!m) throw new Error(`Cannot parse shadow: ${part}`);
    const [, x, y, blur, spread, r, g, b, a] = m;
    return `BoxShadow(color: Color.fromRGBO(${r}, ${g}, ${b}, ${Number(a)}), offset: Offset(${x}, ${y}), blurRadius: ${blur}${spread ? `, spreadRadius: ${spread}` : ''})`;
  });
}

const colorLines = [];
for (const [name, value] of Object.entries(tokens.color)) {
  if (typeof value === 'string') {
    colorLines.push(`  static const ${camel(name)} = ${dartColor(value)};`);
    continue;
  }
  colorLines.push('');
  for (const [step, hex] of Object.entries(value)) {
    colorLines.push(`  static const ${camel(`${name}-${step}`)} = ${dartColor(hex)};`);
  }
}
colorLines.push('', '  // Semantic. Build screens from these, not from the primitives above.');
for (const [name, target] of Object.entries(tokens.semantic)) {
  colorLines.push(`  static const ${camel(name)} = ${dartRef(target)};`);
}

const fontFamily = Object.fromEntries(
  Object.entries(tokens.font).map(([key, f]) => [key, f.family]),
);

const tokensDart = `${DART_HEADER}

import 'package:flutter/animation.dart';
import 'package:flutter/painting.dart';

import 'raad_icons.dart';

/// Raad colours. Rules: navy text on yellow only (never white on yellow); green only for
/// done/arrived; red only for late, SOS and destructive actions.
abstract final class RaadColors {
${colorLines.join('\n')}
}

/// 4-pt spacing scale.
abstract final class RaadSpace {
${Object.entries(tokens.space)
  .map(([step, px]) => `  static const double s${step} = ${px};`)
  .join('\n')}
}

abstract final class RaadRadius {
${Object.entries(tokens.radius)
  .map(([name, px]) => `  static const double ${camel(name)} = ${px};`)
  .join('\n')}
}

/// Navy-tinted elevation.
abstract final class RaadShadows {
${Object.entries(tokens.shadow)
  .map(
    ([name, value]) =>
      `  static const List<BoxShadow> ${/^\d/.test(name) ? `e${name}` : camel(name)} = [\n    ${dartShadows(value).join(',\n    ')},\n  ];`,
  )
  .join('\n')}
}

abstract final class RaadMotion {
${Object.entries(tokens.motion.duration)
  .map(([name, ms]) => `  static const ${camel(name)} = Duration(milliseconds: ${ms});`)
  .join('\n')}
${Object.entries(tokens.motion.easing)
  .map(([name, c]) => `  static const ${camel(`ease-${name}`)} = Cubic(${c.join(', ')});`)
  .join('\n')}
}

abstract final class RaadFonts {
  /// Fonts are bundled in raad_core, so TextStyles must pass \`package: RaadFonts.package\`.
  static const package = 'raad_core';
${Object.entries(fontFamily)
  .map(([key, family]) => `  static const ${key} = ${dartString(family)};`)
  .join('\n')}
}

/// Trip and bus statuses. Always show icon + word + colour, never colour alone.
enum RaadStatus {
${Object.entries(tokens.status)
  .map(
    ([name, s]) =>
      `  ${camel(name)}(\n    bg: RaadColors.${dartRef(s.bg)},\n    fg: RaadColors.${dartRef(s.fg)},\n    icon: RaadIcons.${camel(s.icon)},\n    en: ${dartString(s.en)},\n    so: ${dartString(s.so)},\n  )`,
  )
  .join(',\n')};

  const RaadStatus({
    required this.bg,
    required this.fg,
    required this.icon,
    required this.en,
    required this.so,
  });

  final Color bg;
  final Color fg;
  final RaadIcons icon;

  /// English label.
  final String en;

  /// Somali label.
  final String so;
}
`;

const textDart = `${DART_HEADER}

import 'package:flutter/painting.dart';

import 'raad_tokens.dart';

/// Raad text styles (Typography board). Colour is left unset so the theme or caller decides.
/// Fonts are variable, so each style sets the \`wght\` axis as well as \`fontWeight\`.
/// \`overline\` and \`th\` are uppercase in the design: uppercase the string itself.
abstract final class RaadText {
${Object.entries(tokens.text)
  .map(([name, t]) => {
    const props = [
      `fontFamily: RaadFonts.${t.font}`,
      'package: RaadFonts.package',
      `fontSize: ${t.size}`,
      `height: ${+(t.lineHeight / t.size).toFixed(4)}`,
      `fontWeight: FontWeight.w${t.weight}`,
      `fontVariations: [FontVariation('wght', ${t.weight})]`,
    ];
    if (t.tracking) props.push(`letterSpacing: ${+(t.tracking * t.size).toFixed(3)}`);
    if (t.tabular) props.push('fontFeatures: [FontFeature.tabularFigures()]');
    const doc = `${tokens.font[t.font].family} ${t.weight} · ${t.size}/${t.lineHeight}${t.tracking ? ` · ${t.tracking}em` : ''}${t.uppercase ? ' · uppercase' : ''}${t.flutter ? ` · TextTheme.${t.flutter}` : ''}`;
    return `  /// ${doc}\n  static const ${camel(name)} = TextStyle(\n    ${props.join(',\n    ')},\n  );`;
  })
  .join('\n\n')}
}

`;

const iconsDart = `${DART_HEADER}

/// Raad UI icons: 24×24 grid, 2px round stroke. \`svg\` is the inner markup; RaadIcon wraps it.
enum RaadIcons {
${names.map((n) => `  ${camel(n)}(${dartString(icons[n])})`).join(',\n')};

  const RaadIcons(this.svg);

  final String svg;
}
`;

const dartDir = join(root, 'app', 'raad_core', 'lib', 'theme', 'generated');
mkdirSync(dartDir, { recursive: true });
writeFileSync(join(dartDir, 'raad_tokens.dart'), tokensDart);
writeFileSync(join(dartDir, 'raad_text.dart'), textDart);
writeFileSync(join(dartDir, 'raad_icons.dart'), iconsDart);
try {
  // Keep generated Dart in the standard format so regenerating gives a clean diff.
  execSync(`dart format --page-width 100 "${dartDir}"`, { stdio: 'ignore' });
} catch {
  console.warn('dart not found: generated Dart files were not formatted');
}

console.log(
  `raad tokens: ${vars.length} CSS variables, ${utilities.length} text styles, ${names.length} icons, ${Object.keys(tokens.status).length} statuses (web + Flutter)`,
);
